-- The per-type channel preference matrix: one row per recipient and type. A recipient with no row takes the type's default channels, and an unsubscribable type has no row.
-- tenant_id leads the key as on every scoped table; the identifier is generated by the module, so the key is the tenant and the identifier together.
-- The channels are a stable-sorted JSON array kept as text, opaque to the statement path. The unique index makes a concurrent upsert of one key leave one row.
CREATE TABLE IF NOT EXISTS notification_preferences (
    id                TEXT      NOT NULL,
    tenant_id         TEXT      NOT NULL,
    recipient_user_id TEXT      NOT NULL,
    type_key          TEXT      NOT NULL,
    channels          TEXT      NOT NULL,
    created_at        TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP NOT NULL,
    PRIMARY KEY (tenant_id, id)
);

CREATE UNIQUE INDEX IF NOT EXISTS notification_preferences_recipient_type_idx
    ON notification_preferences (tenant_id, recipient_user_id, type_key);
